def extostr(cls, e, max_level=30, max_path_level=5):
    import traceback
    import os

    def format_path(p, max_level):
        parts = p.split(os.sep)
        if len(parts) > max_level:
            return os.sep.join(['[...]', *parts[-max_path_level:]])
        return p

    exc_type, exc_value, exc_traceback = e.__class__, e, e.__traceback__
    tb_lines = traceback.format_exception(exc_type, exc_value, exc_traceback)
    formatted_lines = []

    for i, line in enumerate(tb_lines):
        if i >= max_level:
            formatted_lines.append('[...]\n')
            break
        if 'File "' in line:
            path, rest = line.split('"', 1)
            path += '"'
            formatted_path = format_path(path[6:], max_path_level)
            line = f'File "{formatted_path}{rest}'
        formatted_lines.append(line)

    return ''.join(formatted_lines)

