def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    for i, (observed, resp) in enumerate(zip(observer_schema, response)):
        if i >= len(last_applied_manifest):
            last_applied_manifest.append(None)
        if isinstance(observed, dict) and isinstance(resp, dict):
            if i >= len(last_applied_manifest) or not isinstance(last_applied_manifest[i], dict):
                last_applied_manifest[i] = {}
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[i], observed, resp)
        elif isinstance(observed, list) and isinstance(resp, list):
            if i >= len(last_applied_manifest) or not isinstance(last_applied_manifest[i], list):
                last_applied_manifest[i] = []
            update_last_applied_manifest_list_from_resp(last_applied_manifest[i], observed, resp)
        elif i >= len(last_applied_manifest) or last_applied_manifest[i] is None:
            last_applied_manifest[i] = resp

