def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		if isinstance(params, dict):
			out_params = {f":{key}": value for key, value in params.items()}
			for key in out_params:
				sql = sql.replace(f":{key[1:]}", key)
		else:
			out_params = [f":{i}" for i in range(1, len(params) + 1)]
			for i, param in enumerate(out_params):
				sql = sql.replace(f"%s", param, 1)
		return sql, out_params

