def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                if isinstance(right, tuple) and len(right) == 3:
                    right_op, right_left, right_right = right
                    if right_op == '|':
                        if left == right_left:
                            result.append(left)
                        elif left == ('~', right_left):
                            result.append(('&', left, right_right))
                    else:
                        result.append(expr)
                else:
                    result.append(expr)
            elif op == '|':
                if isinstance(right, tuple) and len(right) == 3:
                    right_op, right_left, right_right = right
                    if right_op == '&':
                        if left == right_left:
                            result.append(left)
                        elif left == ('~', right_left):
                            result.append(('|', left, right_right))
                    else:
                        result.append(expr)
                else:
                    result.append(expr)
            else:
                result.append(expr)
        else:
            result.append(expr)
    return result

