def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    graph_points = []
    for bin_info in hist:
        bin_content = bin_info['content']
        if get_coordinate == "left":
            x = bin_info['left']
        elif get_coordinate == "right":
            x = bin_info['right']
        elif get_coordinate == "middle":
            x = (bin_info['left'] + bin_info['right']) / 2
        else:
            raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

        y_values = make_value(bin_content)
        if not isinstance(y_values, tuple):
            y_values = (y_values,)

        if len(y_values) != len(field_names) - 1:
            raise ValueError(f"Number of values from make_value ({len(y_values)}) must match number of field names minus x ({len(field_names) - 1})")

        point = {'x': x}
        for i, value in enumerate(y_values):
            point[field_names[i + 1]] = value
        graph_points.append(point)

    graph = {'points': graph_points}
    if scale is True:
        graph['scale'] = hist['scale']
    elif scale is not None:
        graph['scale'] = scale

    return graph

