def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide the interface {iface}")

    required_methods = set(iface.names(all=True))
    candidate_methods = set(dir(candidate))

    missing_methods = required_methods - candidate_methods
    if missing_methods:
        errors.extend(f"Method {method} is not defined" for method in missing_methods)

    for method_name in required_methods:
        if method_name in candidate_methods:
            required_sig = iface[method_name]
            candidate_method = getattr(candidate, method_name)
            try:
                iface._validate_signature(required_sig, candidate_method)
            except zope.interface.Invalid as e:
                errors.append(f"Method {method_name} has incorrect signature: {e}")

    required_attrs = set(iface.names(all=True, only_from=iface))
    candidate_attrs = set(vars(candidate))
    missing_attrs = required_attrs - candidate_attrs
    if missing_attrs:
        errors.extend(f"Attribute {attr} is not defined" for attr in missing_attrs)

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("\n".join(errors))

    return True

