def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    tags = set()
    code_block = False
    result = []

    lines = text.split('\n')
    for line in lines:
        if line.strip().startswith('```'):
            code_block = not code_block
        if not code_block:
            match = re.finditer(r'(?<!\w)(#\w+)(?!\w)', line)
            for m in match:
